-- ============================================================
-- SEED EXT 2: Módulo 23 — Advanced Modals (exercícios 71-165)
-- Novos tópicos: used to vs would (estados vs ações), semi-modais
-- (be supposed to / be likely to / be bound to / be able to),
-- passive perfect modals, TOEFL C1 production
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'advanced-modals';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo advanced-modals não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: used to vs would — estados vs ações habituais
  (cid,11,71,'multiple_choice','What is the key grammatical distinction between "used to" and "would" for past habits?','"Would" can only replace "used to" for repeated actions, NOT for states (live, be, have, believe, know).','["\"Would\" and \"used to\" are always interchangeable","\"Would\" can only replace \"used to\" for repeated actions, NOT for states (live, be, have, believe, know).","\"Used to\" is more formal than \"would\"","\"Would\" can only be used for past states"]','"I used to live in Paris" → correct. "I would live in Paris" → wrong (live = state).','hard'),
  (cid,11,72,'gap_fill','He _____ (live) in a small apartment before he became famous. (state verb — choose the correct form)','used to live',NULL,'"Live" is a state verb → cannot use "would." Only "used to live."','hard'),
  (cid,11,73,'gap_fill','Every morning, she _____ (walk) to the library and _____ (spend) three hours reading. (actions — two options)','would walk / would spend OR used to walk / used to spend',NULL,'"Walk" and "spend" = actions → both "used to" and "would" are correct.','medium'),
  (cid,11,74,'multiple_choice','Which sentence is INCORRECT?','She would believe in the theory before the contradictory evidence emerged.','["She would review the data every morning before the lab opened.","She used to believe in the theory before the contradictory evidence emerged.","She would believe in the theory before the contradictory evidence emerged.","Scientists would dismiss anomalous findings in the early days of the field."]','"Believe" = state verb. "Would believe" for past state = incorrect. Must use "used to believe."','hard'),
  (cid,11,75,'gap_fill','There _____ (used to / there structure) a large forest where the industrial complex now stands.','used to be',NULL,'"There used to be" = past state. "There would be" = incorrect for states.','medium'),
  (cid,11,76,'multiple_choice','Which pair is BOTH correct?','"She used to study late / She would study late" (action).','["She used to know him / She would know him (state — second incorrect)","She used to be shy / She would be shy (state — second incorrect)","She used to study late / She would study late (action).","She used to have a dog / She would have a dog (state — second incorrect)"]','"Study" = action → both forms correct. State verbs (know, be, have) = only "used to."','hard'),
  (cid,11,77,'gap_fill','Scientists _____ (believe/past habit) that the atom was the smallest particle — until subatomic particles were discovered. (state verb)','used to believe',NULL,'"Believe" = state. Only "used to believe" is correct.','medium'),

  -- BLOCK 12: semi-modals — be supposed to, be likely to, be bound to, be about to
  (cid,12,78,'gap_fill','The report _____ (be supposed to / publish/passive) last month, but editing delays pushed the date back.','was supposed to be published',NULL,'"Was supposed to be published" = planned/expected, passive. Was expected but didn''t happen.','hard'),
  (cid,12,79,'multiple_choice','What is the meaning of "be bound to"?','It expresses near certainty that something will happen (= inevitable).','["It expresses obligation","It expresses possibility","It expresses near certainty that something will happen (= inevitable).","It expresses a past prediction"]','"Be bound to + base verb" = it is almost certain / inevitably will happen.','medium'),
  (cid,12,80,'gap_fill','Given the pace of technological change, AI _____ (be bound to / transform) the legal profession within the next decade.','is bound to transform',NULL,'"Is bound to + base verb" = near certainty (strong prediction).','medium'),
  (cid,12,81,'multiple_choice','Which sentence correctly uses "be likely to"?','Sea levels are likely to rise by up to one meter by 2100, according to current projections.','["Sea levels are likely rise by up to one meter by 2100.","Sea levels are likely to rise by up to one meter by 2100, according to current projections.","Sea levels likely rise by one meter by 2100.","Sea levels are likely that they rise by one meter."]','"Are likely to + base verb" = adjective + infinitive. "Are likely that" is ungrammatical.','medium'),
  (cid,12,82,'gap_fill','The project _____ (be supposed to / complete/passive) in June, but it ran over budget.','was supposed to be completed',NULL,'Past "was supposed to" = expectation that was not met. Passive perfect.','hard'),
  (cid,12,83,'multiple_choice','What is the difference between "be likely to" and "be bound to"?','"Be likely to" = probable; "be bound to" = nearly certain/inevitable.','["They are synonyms","''Be bound to'' is more formal","''Be likely to'' = probable; ''be bound to'' = nearly certain/inevitable.","''Be bound to'' can only be used for negative outcomes"]','"Likely" = probability (50–90%). "Bound to" = near certainty (95%+).','hard'),
  (cid,12,84,'gap_fill','The train _____ (be about to / depart) when the alarm went off.','was about to depart',NULL,'"Was about to + base verb" = on the point of doing (immediate future in the past).','medium'),

  -- BLOCK 13: be able to — nuances (past, future, perfect)
  (cid,13,85,'gap_fill','Despite three failed attempts, she finally _____ (be able to / complete) the simulation.','was able to complete',NULL,'"Was able to" = achieved success on a specific occasion in the past. NOT "could" (specific achievement).','hard'),
  (cid,13,86,'multiple_choice','When must "was able to" be used instead of "could" for past ability?','For a specific successful achievement: "She was able to solve the equation" (not "could solve").','["Always","Never — they are interchangeable","For a specific successful achievement: ''She was able to solve the equation'' (not ''could solve'').","Only in formal writing"]','"Could" = general ability. "Was able to" = specific successful occasion.','hard'),
  (cid,13,87,'gap_fill','By next year, the team _____ (be able to / deploy) the new infrastructure across all campuses.','will be able to deploy',NULL,'"Will be able to" = future ability. Not "will can" (can has no infinitive).','medium'),
  (cid,13,88,'multiple_choice','Which sentence uses "have been able to" correctly (present perfect)?','Scientists have been able to sequence the human genome in hours thanks to advances in computing.','["Scientists could sequence the human genome in hours (general ability — imprecise).","Scientists were able to sequence the human genome in hours (specific past event).","Scientists have been able to sequence the human genome in hours thanks to advances in computing.","Scientists can have sequenced the human genome in hours."]','"Have been able to" = achieved over a period up to now. Present perfect of ability.','hard'),
  (cid,13,89,'gap_fill','Had the equipment not malfunctioned, they _____ (be able to / collect) the data in time. (third conditional)','would have been able to collect',NULL,'Third conditional + ability: would have been able to (not "would have could").','hard'),
  (cid,13,90,'multiple_choice','Which modal expression is grammatically IMPOSSIBLE?','She will can finish the project early.','["She will be able to finish the project early.","She has been able to finish projects ahead of schedule.","She would have been able to finish if she had more resources.","She will can finish the project early."]','"Will can" = impossible — modal + modal. Use "will be able to" instead.','hard'),

  -- BLOCK 14: passive perfect modals
  (cid,14,91,'gap_fill','The data _____ (should + analyze + passive) before the conference, but there was no time.','should have been analyzed',NULL,'"Should have been + past participle" = passive perfect modal for criticism of past omission.','hard'),
  (cid,14,92,'multiple_choice','Which sentence uses a passive perfect modal correctly?','The vaccine should have been stored at -20°C, but incorrect temperatures were used.','["The vaccine should have store at -20°C.","The vaccine should have been stored at -20°C, but incorrect temperatures were used.","The vaccine should be stored at -20°C (present advice — not perfect modal).","The vaccine should stored at -20°C."]','"Should have been stored" = passive perfect modal (criticism of past failure).','hard'),
  (cid,14,93,'gap_fill','The error _____ (might + detect + passive) earlier if more robust quality controls had been in place.','might have been detected',NULL,'"Might have been detected" = passive perfect modal for speculation about past alternative.','hard'),
  (cid,14,94,'multiple_choice','"The results could have been skewed by sampling bias." This means:','Sampling bias may have distorted the results in the past.','["The results were definitely skewed","The results will be skewed","Sampling bias may have distorted the results in the past.","Sampling bias definitely skewed the results"]','"Could have been + past participle" = passive speculative modal for the past.','hard'),
  (cid,14,95,'gap_fill','The risks of the procedure _____ (must + communicate + passive) to patients in advance — this was a clear ethical failure.','must have been communicated',NULL,'"Must have been communicated" = past deduction about an obligation.','hard'),
  (cid,14,96,'multiple_choice','Which sentence expresses a missed obligation (passive) most clearly?','The consent forms should have been signed before the data was collected.','["The consent forms should be signed before data collection.","The consent forms must be signed (present obligation).","The consent forms should have been signed before the data was collected.","The consent forms could have been signed."]','"Should have been + past participle" = missed obligation in the past.','hard'),

  -- BLOCK 15: TOEFL Reading
  (cid,15,97,'multiple_choice','[TOEFL Reading] "Scientists used to believe that junk DNA served no function, but recent research has shown that much of it plays a critical regulatory role." The phrase "used to believe" indicates:','This was a past state (belief) that is no longer held.','["Scientists still believe this","This is a future prediction","This was a past state (belief) that is no longer held.","''Used to'' indicates an action not a state"]','"Used to believe" = past state (belief is a state verb). Now revised.','medium'),
  (cid,15,98,'gap_fill','[TOEFL Reading] "The study was supposed to _____ (replicate) by three independent labs, but funding constraints prevented this." Best form?','be replicated',NULL,'"Was supposed to be replicated" = planned passive that did not occur.','hard'),
  (cid,15,99,'multiple_choice','[TOEFL Reading] "Such breakthroughs are bound to alter the way we understand genetic inheritance." "Bound to" implies:','Near certainty — the alteration is considered almost inevitable.','["Possibility","Near certainty — the alteration is considered almost inevitable.","A condition must be met","The change already happened"]','"Be bound to" = near certainty/inevitability.','easy'),
  (cid,15,100,'gap_fill','[TOEFL Reading] "The side effects of the drug _____ (must + document + passive) in pre-clinical trials — the fact that they were not represents a serious regulatory failure." Best form?','must have been documented',NULL,'"Must have been documented" = past deduction about obligation + passive.','hard'),
  (cid,15,101,'multiple_choice','[TOEFL Reading] "Had the data been properly secured, the breach might never have occurred." This is a:','Third conditional with a passive perfect modal.','["Second conditional","First conditional","Third conditional with a passive perfect modal.","A present subjunctive"]','Had + past participle (type 3 if-clause) + might never have occurred (passive perfect modal result).','hard'),

  -- BLOCK 16: TOEFL Speaking
  (cid,16,102,'production','[TOEFL Speaking — 45s] Discuss how scientific research has changed over the past century. Use: used to (state), would (repeated action), be likely to (prediction), be bound to, have been able to.','',NULL,'Scientists used to believe that the universe was static — a view that persisted until the 20th century. They would gather data manually and wait years for publication. Thanks to digital technology, researchers have been able to conduct and disseminate large-scale studies far more efficiently than their predecessors. AI-assisted analysis is likely to accelerate discovery even further. Indeed, the pace of scientific progress is bound to increase as computing power continues to expand.','hard'),
  (cid,16,103,'production','[TOEFL Speaking — 45s] A professor says an important policy change was poorly implemented. Use passive perfect modals: should have been, could have been, must have been, might have been.','',NULL,'The policy should have been piloted in a small number of regions before national rollout. The potential risks must have been identified during the planning phase, yet they appear to have been ignored. Communication strategies could have been improved — clearer messaging might have been issued months before the changes took effect. The absence of proper consultation suggests that key stakeholders must not have been included in the decision-making process.','hard'),

  -- BLOCK 17: TOEFL Writing
  (cid,17,104,'production','[TOEFL Writing — 150 words] Write an academic paragraph analyzing the failure of a historical policy (e.g., Prohibition in the USA, 1920–1933). Use: used to (state), would (action), should have been, could have been, was supposed to, bound to, be likely to.','',NULL,'During Prohibition, the American government used to believe that banning alcohol would reduce crime and increase productivity. Citizens would circumvent the law through speakeasies and bootleggers, generating enormous profits for organized crime. The policy was supposed to create a more virtuous society, but it was bound to fail — demand for alcohol did not disappear simply because supply was restricted. The social consequences should have been anticipated; economists could have been consulted before the legislation was enacted. The unintended empowerment of criminal networks might have been avoided had regulators implemented a taxation and regulation model instead. The evidence suggests that prohibition-based approaches to substance control are likely to produce similar counterproductive outcomes in any context where underlying demand remains unaddressed.','hard'),
  (cid,17,105,'production','[TOEFL Writing — Error Correction] Fix modal errors: "She use to work there. He would be a famous painter before he became ill (state). The risks should been communicated earlier. Researchers were able to proving the theory after years of work. The vaccine must have distributed globally — it was not."','',NULL,'use to → used to; would be → used to be (be = state, cannot use would); should been → should have been (perfect modal requires have); able to proving → able to prove (to + base verb); must have distributed → must have been distributed (passive perfect modal).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
